func TestComputePatchID(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)

	// Create initial commit
	testutil.WriteFile(t, dir, "file.txt", "initial")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "initial")

	// Create a commit with a known change
	testutil.WriteFile(t, dir, "file.txt", "modified")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "modify file")

	head := testutil.GitRevParse(t, dir, "HEAD")
	parent := testutil.GitRevParse(t, dir, "HEAD~1")

	patchID, err := ComputePatchID(context.Background(), dir, parent, head)
	require.NoError(t, err)
	require.NotEmpty(t, patchID)
	// Patch ID is a 40-char hex SHA1
	require.Len(t, patchID, 40)
}

func TestComputePatchID_StableAcrossRebase(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)

	// Create base commit
	testutil.WriteFile(t, dir, "base.txt", "base")
	testutil.GitAdd(t, dir, "base.txt")
	testutil.GitCommit(t, dir, "base")

	// Branch: feature
	testutil.GitCheckoutNewBranch(t, dir, "feature")
	testutil.WriteFile(t, dir, "feature.txt", "feature work")
	testutil.GitAdd(t, dir, "feature.txt")
