	cmd := exec.Command("git", "rebase", onto)
	cmd.Dir = repoDir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git rebase %s failed: %v\n%s", onto, err, string(out))
	}
}
